import { PermissionFlagsBits } from 'discord.js'
import { config } from './config.js'

// =============================================================================
//   Permission & member checks
// =============================================================================

/** Is the channel under a REPLY_CATEGORY_IDS category? A thread counts by its parent channel's category. */
export function inReplyCategory (channel) {
  if (!channel) return false
  const category = channel.isThread?.() ? channel.parent?.parentId : channel.parentId
  return config.replyCategories.has(category)
}

/**
 * Should the bot auto-reply here? This is the only "is this a ticket?" check: the channel must sit under a REPLY_CATEGORY_IDS category, and the bot must be allowed to post there.
 * Posting needs View Channel, Send Messages, Embed Links (the details card) and Read Message History (replies).
 */
export function canReply (channel) {
  const me = channel?.guild?.members.me
  if (!me || !channel.permissionsFor) return false
  if (!inReplyCategory(channel)) return false
  const send = channel.isThread?.() ? PermissionFlagsBits.SendMessagesInThreads : PermissionFlagsBits.SendMessages
  return channel.permissionsFor(me).has([PermissionFlagsBits.ViewChannel, send, PermissionFlagsBits.EmbedLinks, PermissionFlagsBits.ReadMessageHistory])
}

/** Does this member hold a STAFF_ROLE_IDS role? (Their ticket messages are ignored.) */
export function isStaff (member) {
  if (!member?.roles || !config.staffRoles.size) return false
  return member.roles.cache.some((r) => config.staffRoles.has(r.id))
}

// =============================================================================
//   Message helpers
// =============================================================================

/** Every bit of text a message carries, including embeds (Ticket Tool's form). */
export function messageText (message) {
  const parts = [message.content ?? '']
  for (const e of message.embeds ?? []) {
    parts.push(e.title ?? '', e.description ?? '', e.footer?.text ?? '', e.author?.name ?? '', e.url ?? '')
    for (const f of e.fields ?? []) parts.push(f.name ?? '', f.value ?? '')
  }
  return parts.filter(Boolean).join('\n')
}

/**
 * Reply without pinging the author. If the message being replied to was deleted, Discord posts it as a normal message instead of failing.
 */
export function quietReply (message, payload) {
  return message.reply({ ...payload, allowedMentions: { repliedUser: false }, failIfNotExists: false })
}

/** Discord error codes meaning the channel is gone or we lost access to it. */
export const CHANNEL_GONE = new Set([10003, 50001])
